const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let parsed;
try { parsed = JSON.parse(clean); } catch(e) { parsed = { decision_finale:"GO", ca_perdu_estime:"Non calcule", hook_principal:"Votre site perd des clients", brain_synthesis:"Site avec problemes", score_opportunite:60, next_action:"email_immediat", instructions_stratege:"Focus conversion", instructions_architecte:"Mobile-first", instructions_copywriter:"Direct et chiffre", criteres_validation:{stratege:"angle present",architecte:"pages listees",copywriter:"hook et CA mentionnes"} }; }
return [{ json: { brain_final: parsed, brain_go_final: (parsed.decision_finale || parsed.decision)==="GO", prospect: $("✅ Init").first().json, audit: $("🔬 Audit Ultra").first().json, brain_decision_1: $("📋 Parse Décision 1").first().json.brain_decision_1, retry_state: $("✅ Init").first().json.retry_state } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let ev;
try { ev = JSON.parse(clean); } catch(e) { ev = { verdict:"APPROVE", score:70, raisons:[], instruction_retry:"" }; }
const prev = $("📋 Parse Plan Final").first().json;
const rc = prev.retry_state?.stratege ?? 0;
const approved = ev.verdict==="APPROVE" || rc >= (prev.retry_state?.max ?? 2);
return [{ json: { stratege_output: $("🎯 Stratège").first().json, stratege_eval: ev, stratege_approved: approved, stratege_retry_instruction: ev.instruction_retry, retry_state: { ...prev.retry_state, stratege: rc+1 }, brain_final: prev.brain_final, brain_decision_1: prev.brain_decision_1, prospect: prev.prospect, audit: prev.audit } }];

const d = $input.first().json;
const stratege_final = d.stratege_output || d;
return [{ json: { stratege_final, brain_final: $("📋 Parse Plan Final").first().json.brain_final, brain_decision_1: $("📋 Parse Plan Final").first().json.brain_decision_1, prospect: $("📋 Parse Plan Final").first().json.prospect, audit: $("📋 Parse Plan Final").first().json.audit, retry_state: $("📋 Parse Eval Stratège").first().json.retry_state } }];

