const d = $input.first().json;
const archi_final = d.architecte_output || d;
return [{ json: { archi_final, stratege_final: $("📋 Parse Eval Architecte").first().json.stratege_final, brain_final: $("📋 Parse Plan Final").first().json.brain_final, brain_decision_1: $("📋 Parse Plan Final").first().json.brain_decision_1, prospect: $("📋 Parse Plan Final").first().json.prospect, audit: $("📋 Parse Plan Final").first().json.audit, retry_state: $("📋 Parse Eval Architecte").first().json.retry_state } }];

const raw = $input.first().json;
const text = raw?.content?.find(c=>c.type==="text")?.text || "{}";
const clean = text.replace(/```json\n?/g,"").replace(/```/g,"").trim();
let ev;
try { ev = JSON.parse(clean); } catch(e) { const copy = $("✍️ Copywriter").first().json; ev = { verdict:"APPROVE", qualite_score:65, envoyable:true, raisons_rejet:[], objet_final: copy.objet||copy.variante_a?.objet||"", corps_final: copy.corps||copy.variante_a?.corps||"", brain_note:"Fallback", instruction_retry:"" }; }
if (ev.corps_final && !ev.corps_final.toLowerCase().includes("opt-out")) { ev.corps_final += "\n\n---\nSi vous ne souhaitez plus recevoir ce type d analyses, repondez simplement Opt-out."; }
const prev = $("✨ Best Architecte").first().json;
const rc = prev.retry_state?.copywriter ?? 0;
const approved = (ev.verdict==="APPROVE" || rc >= (prev.retry_state?.max ?? 2)) && ev.envoyable && ev.qualite_score >= 60;
return [{ json: { copywriter_eval: ev, copywriter_approved: approved, copywriter_retry_instruction: ev.instruction_retry, retry_state: { ...prev.retry_state, copywriter: rc+1 }, brain_final: prev.brain_final, brain_decision_1: prev.brain_decision_1, prospect: prev.prospect, audit: prev.audit, stratege_final: prev.stratege_final, archi_final: prev.archi_final } }];

const d = $input.first().json;
const hasEmail = !!d.prospect.email;
return [{ json: { nom: d.prospect.nom, site_web: d.prospect.site_web, secteur: d.prospect.secteur, ville: d.prospect.ville, email: d.prospect.email, score_opportunite: d.brain_final?.score_opportunite || 0, score_qualite_email: d.copywriter_eval?.qualite_score || 0, email_objet: d.copywriter_eval?.objet_final || "", email_body: d.copywriter_eval?.corps_final || "", brain_synthesis: d.brain_final?.brain_synthesis, brain_ca_perdu: d.brain_final?.ca_perdu_estime, brain_note: d.copywriter_eval?.brain_note, priorite: d.brain_decision_1?.priorite || "moyenne", retries_used: d.retry_state, status: hasEmail ? "email_ready" : "no_email", pipeline_completed_at: new Date().toISOString() } }];
